import androidx.compose.runtime.*
import org.hermesmobile.app.data.AppPreferences

/** Independent English, Simplified Chinese and accented Hanyu Pinyin entries. */
enum class Words(val en: String, val zh: String, val pin: String) {
    HostMoa("Mixture-of-Agents presets","多智能体混合预设","Duō zhìnéng tǐ hùnhé yùshè"),
    HostMoaRead("Read presets and model catalogs","读取预设及模型目录","Dúqǔ yùshè jí móxíng mùlù"),
    HostMoaReadEffect("Reads this profile’s normalized named presets, selectors and privacy-filter mode, together with the main/auxiliary configuration and provider catalogs. Reported defaults may replace invalid stored values. No model inference is requested.","读取此配置规范化后的命名预设、选择项和隐私过滤模式，以及主模型、辅助任务配置和提供方目录。报告的默认值可能替代无效的存储值。不会请求模型推理。","Dúqǔ cǐ pèizhì guīfànhuà hòu de mìngmíng yùshè, xuǎnzé xiàng hé yǐnsī guòlǜ móshì, yǐjí zhǔ móxíng, fǔzhù rènwù pèizhì hé tígōng fāng mùlù. Bàogào de mòrèn zhí kěnéng tìdài wúxiào de cúnchǔ zhí. Bú huì qǐngqiú móxíng tuīlǐ."),
    HostMoaUnavailable("The MoA configuration is incomplete, inconsistent or outside supported bounds. Read it again after checking Hermes.","MoA 配置不完整、不一致或超出支持范围。请检查 Hermes 后重新读取。","MoA pèizhì bù wánzhěng, bù yízhì huò chāochū zhīchí fànwéi. Qǐng jiǎnchá Hermes hòu chóngxīn dúqǔ."),
    HostMoaDraft("Edits stay on this phone until a separate full-map review and confirmation. Closing discards the draft.","编辑保留在手机上，直到单独审阅并确认完整预设映射。关闭会丢弃草稿。","Biānjí bǎoliú zài shǒujī shàng, zhídào dāndú shěnyuè bìng quèrèn wánzhěng yùshè yìngshè. Guānbì huì diūqì cǎogǎo."),
    HostMoaDefault("Configured default preset","配置的默认预设","Pèizhì de mòrèn yùshè"),
    HostMoaActive("Configured active preset","配置的活动预设","Pèizhì de huódòng yùshè"),
    HostMoaInactive("No configured active preset","未配置活动预设","Wèi pèizhì huódòng yùshè"),
    HostMoaPrivacy("Reported privacy-filter mode (read-only here)","报告的隐私过滤模式（此处只读）","Bàogào de yǐnsī guòlǜ móshì (cǐ chù zhǐ dú)"),
    HostMoaPrivacyEffect("This endpoint preserves the host’s stored privacy-filter policy and cannot edit it.","此端点保留主机存储的隐私过滤策略，无法编辑它。","Cǐ duāndiǎn bǎoliú zhǔjī cúnchǔ de yǐnsī guòlǜ cèlüè, wúfǎ biānjí tā."),
    HostMoaNewName("New preset name","新预设名称","Xīn yùshè míngchēng"),
    HostMoaDuplicate("Duplicate reported preset","复制报告的预设","Fùzhì bàogào de yùshè"),
    HostMoaRemove("Remove preset from draft","从草稿移除预设","Cóng cǎogǎo yíchú yùshè"),
    HostMoaAtLeastOne("At least one preset and one reference must remain.","必须至少保留一个预设和一个参考模型。","Bìxū zhìshǎo bǎoliú yí gè yùshè hé yí gè cānkǎo móxíng."),
    HostMoaEdit("Edit preset","编辑预设","Biānjí yùshè"),
    HostMoaReferences("Reference models (ordered)","参考模型（有序）","Cānkǎo móxíng (yǒuxù)"),
    HostMoaAggregator("Aggregator model","聚合模型","Jùhé móxíng"),
    HostMoaAddReference("Add reference model","添加参考模型","Tiānjiā cānkǎo móxíng"),
    HostMoaCopyReference("Duplicate reference","复制参考模型","Fùzhì cānkǎo móxíng"),
    HostMoaRemoveReference("Remove reference","移除参考模型","Yíchú cānkǎo móxíng"),
    HostMoaMoveUp("Move earlier","向前移动","Xiàng qián yídòng"),
    HostMoaMoveDown("Move later","向后移动","Xiàng hòu yídòng"),
    HostMoaReferenceTemperature("Reference temperature (blank = provider default)","参考模型温度（空白为提供方默认值）","Cānkǎo móxíng wēndù (kòngbái wéi tígōng fāng mòrèn zhí)"),
    HostMoaAggregatorTemperature("Aggregator temperature (blank = provider default)","聚合模型温度（空白为提供方默认值）","Jùhé móxíng wēndù (kòngbái wéi tígōng fāng mòrèn zhí)"),
    HostMoaTimeout("Reference timeout seconds (blank = host inheritance)","参考模型超时秒数（空白为继承主机设置）","Cānkǎo móxíng chāoshí miǎo shù (kòngbái wéi jìchéng zhǔjī shèzhì)"),
    HostMoaCadence("Reference call cadence","参考模型调用频率","Cānkǎo móxíng diàoyòng pínlǜ"),
    HostMoaPerTurn("Once per user turn","每次用户回合一次","Měi cì yònghù huíhé yí cì"),
    HostMoaPerIteration("Each tool iteration","每次工具迭代","Měi cì gōngjù diédài"),
    HostMoaEveryN("Every N iterations (N ≥ 2)","每 N 次迭代（N ≥ 2）","Měi N cì diédài (N ≥ 2)"),
    HostMoaFailurePolicy("Failed-reference disclosure","参考模型失败的披露","Cānkǎo móxíng shībài de pīlù"),
    HostMoaLoud("Disclose failed references","披露失败的参考模型","Pīlù shībài de cānkǎo móxíng"),
    HostMoaSilent("Suppress failed-reference disclosure","不披露参考模型失败","Bù pīlù cānkǎo móxíng shībài"),
    HostMoaReasoningDefault("No preset reasoning override","无预设推理覆盖值","Wú yùshè tuīlǐ fùgài zhí"),
    HostMoaAggClearUnsupported("Hermes merges surviving aggregator fields and cannot clear an existing reasoning override through this endpoint. Choose a canonical level or edit it in Hermes.","Hermes 会合并保留的聚合模型字段，此端点无法清除现有推理覆盖值。请选择标准级别，或在 Hermes 中编辑。","Hermes huì hébìng bǎoliú de jùhé móxíng zìduàn, cǐ duāndiǎn wúfǎ qīngchú xiànyǒu tuīlǐ fùgài zhí. Qǐng xuǎnzé biāozhǔn jíbié, huò zài Hermes zhōng biānjí."),
    HostMoaUnrepresentable("A reported reasoning value cannot round-trip through this API. Editing is disabled to preserve it; correct it in Hermes and read again.","报告的推理值无法通过此 API 原样往返。为保留它，已禁用编辑；请在 Hermes 中修正后重新读取。","Bàogào de tuīlǐ zhí wúfǎ tōngguò cǐ API yuányàng wǎngfǎn. Wèi bǎoliú tā, yǐ jìnyòng biānjí; qǐng zài Hermes zhōng xiūzhèng hòu chóngxīn dúqǔ."),
    HostMoaRecursive("MoA cannot be nested inside a preset.","预设内不能嵌套 MoA。","Yùshè nèi bù néng qiàntào MoA."),
    HostMoaLimit("The supported preset/reference limit has been reached.","已达到支持的预设或参考模型数量上限。","Yǐ dádào zhīchí de yùshè huò cānkǎo móxíng shùliàng shàngxiàn."),
    HostMoaReview("Review full preset-map replacement","审阅完整预设映射替换","Shěnyuè wánzhěng yùshè yìngshè tìhuàn"),
    HostMoaAdded("Added preset names","新增预设名称","Xīnzēng yùshè míngchēng"),
    HostMoaRemoved("Removed preset names","移除的预设名称","Yíchú de yùshè míngchēng"),
    HostMoaChanged("Changed preset names","更改的预设名称","Gēnggǎi de yùshè míngchēng"),
    HostMoaEffect("Replaces the complete named preset map for this profile: omitted names are deleted. Saving may persist reported defaults that repaired invalid stored values. Hermes merges surviving preset and aggregator dictionaries but replaces reference lists; hidden reference-slot extensions can be lost. A duplicate contains only reported supported fields. More references, frequent cadence, timeout and reasoning choices can increase provider calls, cost and data sharing. This save has no model-selection warning guard or inference/credential test.","替换此配置的完整命名预设映射：省略的名称会被删除。保存可能写入修复无效存储值后报告的默认值。Hermes 会合并保留的预设和聚合模型字典，但会替换参考模型列表；隐藏的参考槽位扩展可能丢失。副本只包含报告的受支持字段。更多参考模型、更频繁的调用、超时及推理选择可能增加提供方调用、费用和数据共享。此保存没有模型选择警告防护，也不测试推理或凭据。","Tìhuàn cǐ pèizhì de wánzhěng mìngmíng yùshè yìngshè: shěnglüè de míngchēng huì bèi shānchú. Bǎocún kěnéng xiěrù xiūfù wúxiào cúnchǔ zhí hòu bàogào de mòrèn zhí. Hermes huì hébìng bǎoliú de yùshè hé jùhé móxíng zìdiǎn, dàn huì tìhuàn cānkǎo móxíng lièbiǎo; yǐncáng de cānkǎo cáowèi kuòzhǎn kěnéng diūshī. Fùběn zhǐ bāohán bàogào de shòu zhīchí zìduàn. Gèng duō cānkǎo móxíng, gèng pínfán de diàoyòng, chāoshí jí tuīlǐ xuǎnzé kěnéng zēngjiā tígōng fāng diàoyòng, fèiyòng hé shùjù gòngxiǎng. Cǐ bǎocún méiyǒu móxíng xuǎnzé jǐnggào fánghù, yě bù cèshì tuīlǐ huò píngjù."),
    HostMoaConcurrency("Fresh reads check the normalized map and selected public catalog metadata. Hidden credentials/endpoints, raw-file repairs, host policy and later concurrent writers remain unverified; there is no revision guard. Null timeout inherits an uninspected host MoA-reference timeout. Running sessions and phone model choices are separate. Cancelling the phone wait cannot undo host work.","重新读取会检查规范化映射及所选目录的公开元数据。隐藏的凭据、端点、原始文件修复、主机策略和随后并发写入者仍未验证；没有修订版本防护。空超时值继承未检查的主机 MoA 参考模型超时。运行中的会话及手机模型选择是独立的。取消手机等待无法撤销主机工作。","Chóngxīn dúqǔ huì jiǎnchá guīfànhuà yìngshè jí suǒ xuǎn mùlù de gōngkāi yuán shùjù. Yǐncáng de píngjù, duāndiǎn, yuánshǐ wénjiàn xiūfù, zhǔjī cèlüè hé suíhòu bìngfā xiěrù zhě réng wèi yànzhèng; méiyǒu xiūdìng bǎnběn fánghù. Kōng chāoshí zhí jìchéng wèi jiǎnchá de zhǔjī MoA cānkǎo móxíng chāoshí. Yùnxíng zhōng de huìhuà jí shǒujī móxíng xuǎnzé shì dúlì de. Qǔxiāo shǒujī děngdài wúfǎ chèxiāo zhǔjī gōngzuò."),
    HostMoaApprove("I approve this complete preset map, deletions and the effects above","我批准此完整预设映射、删除及上述影响","Wǒ pīzhǔn cǐ wánzhěng yùshè yìngshè, shānchú jí shàngshù yǐngxiǎng"),
    HostMoaAcknowledged("Preset-map save acknowledged. Current configuration is shown separately from runtime adoption.","预设映射保存已确认。当前配置与运行时采用情况单独显示。","Yùshè yìngshè bǎocún yǐ quèrèn. Dāngqián pèizhì yǔ yùnxíng shí cǎiyòng qíngkuàng dāndú xiǎnshì."),
    HostMoaNormalized("Hermes acknowledged a different normalized preset map. Review the reported configuration before using it.","Hermes 确认了不同的规范化预设映射。使用前请审阅报告的配置。","Hermes quèrèn le bùtóng de guīfànhuà yùshè yìngshè. Shǐyòng qián qǐng shěnyuè bàogào de pèizhì."),
    HostMoaRequestedHash("Requested public configuration fingerprint","请求的公开配置指纹","Qǐngqiú de gōngkāi pèizhì zhǐwén"),
    HostMoaReportedHash("Host-reported public configuration fingerprint","主机报告的公开配置指纹","Zhǔjī bàogào de gōngkāi pèizhì zhǐwén"),
    HostMoaReceipt("Receipts retain public configuration fingerprints, selectors and changed-name lists, not full maps or private metadata. Acknowledgement/readback does not prove exact disk contents, preservation of unknown fields, causality, provider health or running-session adoption. Observe through a new preset read review; unknown saves are never replayed automatically.","回执保留公开配置指纹、选择项及更改名称列表，不保留完整映射或私密元数据。确认或回读不证明确切磁盘内容、未知字段的保留、因果关系、提供方健康状况或运行中会话的采用情况。请通过新的预设读取审阅查看；结果未知的保存不会自动重放。","Huízhí bǎoliú gōngkāi pèizhì zhǐwén, xuǎnzé xiàng jí gēnggǎi míngchēng lièbiǎo, bù bǎoliú wánzhěng yìngshè huò sīmì yuán shùjù. Quèrèn huò huídú bù zhèngmíng quèqiè cípán nèiróng, wèizhī zìduàn de bǎoliú, yīnguǒ guānxì, tígōng fāng jiànkāng zhuàngkuàng huò yùnxíng zhōng huìhuà de cǎiyòng qíngkuàng. Qǐng tōngguò xīn de yùshè dúqǔ shěnyuè chákàn; jiéguǒ wèizhī de bǎocún bú huì zìdòng chóngfàng."),
    HostAuxMinimal("Minimal","最低","Zuì dī"),
    HostAuxLow("Low","低","Dī"),
    HostAuxMedium("Medium","中","Zhōng"),
    HostAuxHigh("High","高","Gāo"),
    HostAuxXhigh("Extra high","很高","Hěn gāo"),
    HostAuxMax("Maximum","最大","Zuì dà"),
    HostAuxUltra("Ultra","超高","Chāo gāo"),
    HostAuxEdit("Edit auxiliary assignment","编辑辅助任务分配","Biānjí fǔzhù rènwù fēnpèi"),
    HostAuxReview("Review auxiliary assignment","审阅辅助任务分配","Shěnyuè fǔzhù rènwù fēnpèi"),
    HostAuxAll("Assign all current auxiliary slots","分配所有当前辅助任务槽位","Fēnpèi suǒyǒu dāngqián fǔzhù rènwù cáowèi"),
    HostAuxReset("Reset all auxiliary assignments","重置所有辅助任务分配","Chóngzhì suǒyǒu fǔzhù rènwù fēnpèi"),
    HostAuxAuto("Use auto routing","使用自动路由","Shǐyòng zìdòng lùyóu"),
    HostAuxKeep("Keep reasoning unchanged","保持推理设置不变","Bǎochí tuīlǐ shèzhì bú biàn"),
    HostAuxInherit("Clear reasoning override / inherit","清除推理覆盖值／继承","Qīngchú tuīlǐ fùgài zhí / jìchéng"),
    HostAuxNone("Disable reasoning (none)","禁用推理（none）","Jìnyòng tuīlǐ (none)"),
    HostAuxRouteEffect("Saves provider/model settings for the selected slots. Keeping the same provider, or selecting bare custom, can retain existing endpoint and credential overrides. Switching to another provider clears those overrides. Auto routing alone is not a complete reset. No endpoint address or secret is sent by the phone. Hermes may contact metadata services for selection warnings.","保存所选槽位的提供方和模型设置。保持同一提供方或选择裸 custom 值可能保留现有端点及凭据覆盖值。切换到其他提供方会清除这些覆盖值。仅自动路由并非完整重置。手机不会发送端点地址或密钥。Hermes 可能联系元数据服务以获取选择警告。","Bǎocún suǒ xuǎn cáowèi de tígōng fāng hé móxíng shèzhì. Bǎochí tóng yī tígōng fāng huò xuǎnzé luǒ custom zhí kěnéng bǎoliú xiànyǒu duāndiǎn jí píngjù fùgài zhí. Qiēhuàn dào qítā tígōng fāng huì qīngchú zhèxiē fùgài zhí. Jǐn zìdòng lùyóu bìng fēi wánzhěng chóngzhì. Shǒujī bú huì fāsòng duāndiǎn dìzhǐ huò mìyuè. Hermes kěnéng liánxì yuán shùjù fúwù yǐ huòqǔ xuǎnzé jǐnggào."),
    HostAuxReasoningEffect("Keep omits reasoning from the request. Inherit explicitly clears the override; disabling sends none. Reset restores shipped defaults, including voice reasoning disabled. Provider support and plugin inheritance can change the effective behavior.","保持不变会在请求中省略推理字段。继承会明确清除覆盖值；禁用会发送 none。重置会恢复内置默认值，包括禁用语音推理。提供方支持及插件继承可能改变实际行为。","Bǎochí bú biàn huì zài qǐngqiú zhōng shěnglüè tuīlǐ zìduàn. Jìchéng huì míngquè qīngchú fùgài zhí; jìnyòng huì fāsòng none. Chóngzhì huì huīfù nèizhì mòrèn zhí, bāokuò jìnyòng yǔyīn tuīlǐ. Tígōng fāng zhīchí jí chājiàn jìchéng kěnéng gǎibiàn shíjì xíngwéi."),
    HostAuxResetEffect("Resets every current dashboard auxiliary slot to auto with an empty model; removes reasoning, endpoint, inline credentials, credential-variable pointers and API-mode overrides. Other task settings remain. Built-in defaults and plugin inheritance can take effect again.","将所有当前仪表板辅助任务槽位重置为 auto 和空模型；移除推理、端点、内联凭据、凭据变量引用及 API 模式覆盖值。其他任务设置保留。内置默认值和插件继承可能再次生效。","Jiāng suǒyǒu dāngqián yíbiǎobǎn fǔzhù rènwù cáowèi chóngzhì wéi auto hé kōng móxíng; yíchú tuīlǐ, duāndiǎn, nèilián píngjù, píngjù biànliàng yǐnyòng jí API móshì fùgài zhí. Qítā rènwù shèzhì bǎoliú. Nèizhì mòrèn zhí hé chājiàn jìchéng kěnéng zàicì shēngxiào."),
    HostAuxBulkEffect("All-slot operations include the host current registered slots, including plugins added after this review. The displayed list is a snapshot. Slots outside the dashboard assignment API are unaffected.","所有槽位操作涵盖主机当前注册的槽位，包括此次审阅后添加的插件。此列表是快照。仪表板分配 API 之外的槽位不受影响。","Suǒyǒu cáowèi cāozuò hángài zhǔjī dāngqián zhùcè de cáowèi, bāokuò cǐ cì shěnyuè hòu tiānjiā de chājiàn. Cǐ lièbiǎo shì kuàizhào. Yíbiǎobǎn fēnpèi API zhīwài de cáowèi bú shòu yǐngxiǎng."),
    HostAuxConcurrency("Preflight and readback can probe the current custom endpoint, contact provider metadata or usage services, warm caches and persist discovered model lists. Visible configuration is checked, but hidden endpoint/credential changes and concurrent writers can remain undetected. Host policy can override saved settings. Running calls may keep a frozen configuration. Cancelling the phone wait cannot undo host saves, probes or cache work.","预检和回读可能探测当前自定义端点、联系提供方元数据或用量服务、预热缓存并保存发现的模型列表。会检查可见配置，但隐藏的端点或凭据变更及并发写入者可能无法发现。主机策略可能覆盖保存的设置。运行中的调用可能保留冻结配置。取消手机等待无法撤销主机保存、探测或缓存工作。","Yùjiǎn hé huídú kěnéng tàncè dāngqián zìdìngyì duāndiǎn, liánxì tígōng fāng yuán shùjù huò yòngliàng fúwù, yùrè huǎncún bìng bǎocún fāxiàn de móxíng lièbiǎo. Huì jiǎnchá kějiàn pèizhì, dàn yǐncáng de duāndiǎn huò píngjù biàngēng jí bìngfā xiěrù zhě kěnéng wúfǎ fāxiàn. Zhǔjī cèlüè kěnéng fùgài bǎocún de shèzhì. Yùnxíng zhōng de diàoyòng kěnéng bǎoliú dòngjié pèizhì. Qǔxiāo shǒujī děngdài wúfǎ chèxiāo zhǔjī bǎocún, tàncè huò huǎncún gōngzuò."),
    HostAuxApprove("I approve these auxiliary changes and the effects above","我批准这些辅助任务更改及上述影响","Wǒ pīzhǔn zhèxiē fǔzhù rènwù gēnggǎi jí shàngshù yǐngxiǎng"),
    HostAuxAcknowledged("Auxiliary assignment acknowledged. Current reported configuration is separate from runtime adoption and credential health.","辅助任务分配已确认。当前报告的配置与运行时采用及凭据健康状况是独立的。","Fǔzhù rènwù fēnpèi yǐ quèrèn. Dāngqián bàogào de pèizhì yǔ yùnxíng shí cǎiyòng jí píngjù jiànkāng zhuàngkuàng shì dúlì de."),
    HostAuxReportedTasks("Host-reported affected slots","主机报告的受影响槽位","Zhǔjī bàogào de shòu yǐngxiǎng cáowèi"),
    HostAuxReceipt("The receipt records the reviewed request and typed host acknowledgement or warning refusal. Reset does not report an exact affected list. Matching readback does not prove exact saved contents, secret removal, inheritance, causality or running-call adoption. Observe through a fresh model read review.","回执记录已审阅的请求及类型正确的主机确认或警告拒绝。重置不会报告确切受影响列表。匹配的回读不证明确切保存内容、密钥移除、继承、因果关系或运行中调用的采用情况。请通过新的模型读取审阅查看。","Huízhí jìlù yǐ shěnyuè de qǐngqiú jí lèixíng zhèngquè de zhǔjī quèrèn huò jǐnggào jùjué. Chóngzhì bú huì bàogào quèqiè shòu yǐngxiǎng lièbiǎo. Pǐpèi de huídú bù zhèngmíng quèqiè bǎocún nèiróng, mìyuè yíchú, jìchéng, yīnguǒ guānxì huò yùnxíng zhōng diàoyòng de cǎiyòng qíngkuàng. Qǐng tōngguò xīn de móxíng dúqǔ shěnyuè chákàn."),
    HostMainNormalized("Hermes reported a different normalized provider/model pair. Review the configured pair before using it for new sessions.","Hermes 报告了不同的规范化提供方与模型组合。用于新会话前，请审阅配置的组合。","Hermes bàogào le bùtóng de guīfànhuà tígōng fāng yǔ móxíng zǔhé. Yòng yú xīn huìhuà qián, qǐng shěnyuè pèizhì de zǔhé."),
    HostMainRequested("Requested selection","请求的选择","Qǐngqiú de xuǎnzé"),
    HostMainReported("Host-reported selection","主机报告的选择","Zhǔjī bàogào de xuǎnzé"),
    HostMainSet("Use as host main model","用作主机主模型","Yòng zuò zhǔjī zhǔ móxíng"),
    HostMainReview("Review main model assignment","审阅主模型分配","Shěnyuè zhǔ móxíng fēnpèi"),
    HostMainEffect("Changes this profile default for new sessions. Hermes can validate credentials, contact providers and start a managed local model runtime. It can normalize model/provider names, replace route and credential references, and clear a route-specific context pin. Selecting Nous can route unconfigured tools through its gateway. Existing auxiliary pins can remain.","更改此配置中新会话的默认模型。Hermes 可能验证凭据、联系提供方并启动托管的本地模型运行时。它可能规范化模型或提供方名称、替换路由及凭据引用，并清除特定路由的上下文固定值。选择 Nous 可能将未配置的工具路由到其网关。现有辅助任务固定值可能保留。","Gēnggǎi cǐ pèizhì zhōng xīn huìhuà de mòrèn móxíng. Hermes kěnéng yànzhèng píngjù, liánxì tígōng fāng bìng qǐdòng tuōguǎn de běndì móxíng yùnxíng shí. Tā kěnéng guīfànhuà móxíng huò tígōng fāng míngchēng, tìhuàn lùyóu jí píngjù yǐnyòng, bìng qīngchú tèdìng lùyóu de shàngxiàwén gùdìng zhí. Xuǎnzé Nous kěnéng jiāng wèi pèizhì de gōngjù lùyóu dào qí wǎngguān. Xiànyǒu fǔzhù rènwù gùdìng zhí kěnéng bǎoliú."),
    HostMainConcurrency("Preflight checks visible metadata. Endpoint or credential changes behind the same names can remain undetected, and other writers can race this save. Running sessions keep their separate runtime choices. Cancelling the phone wait cannot undo host work.","预检会检查可见元数据。同名背后的端点或凭据变更可能无法发现，其他写入者可能与此次保存并发。运行中的会话保留各自的运行时选择。取消手机等待无法撤销主机工作。","Yùjiǎn huì jiǎnchá kějiàn yuán shùjù. Tóngmíng bèihòu de duāndiǎn huò píngjù biàngēng kěnéng wúfǎ fāxiàn, qítā xiěrù zhě kěnéng yǔ cǐ cì bǎocún bìngfā. Yùnxíng zhōng de huìhuà bǎoliú gèzì de yùnxíng shí xuǎnzé. Qǔxiāo shǒujī děngdài wúfǎ chèxiāo zhǔjī gōngzuò."),
    HostMainApprove("I approve this profile assignment and the effects above","我批准此配置分配及上述影响","Wǒ pīzhǔn cǐ pèizhì fēnpèi jí shàngshù yǐngxiǎng"),
    HostMainWarningTitle("Review host selection warning","审阅主机选择警告","Shěnyuè zhǔjī xuǎnzé jǐnggào"),
    HostMainWarningRequired("The host requested selection-warning approval before applying this assignment.","主机要求在应用此分配前批准选择警告。","Zhǔjī yāoqiú zài yìngyòng cǐ fēnpèi qián pīzhǔn xuǎnzé jǐnggào."),
    HostMainWarningEffect("This report can cover price or data-training terms. Confirming approves the displayed warning and sends one new, explicitly reviewed assignment with the selection-warning override. Hermes does not bind that override to a warning revision; changed terms may need another review.","此报告可能涉及价格或数据训练条款。确认即批准显示的警告，并发送一次明确审阅的新分配，覆盖选择警告。Hermes 不会将此覆盖绑定到警告修订版本；条款变化可能需要重新审阅。","Cǐ bàogào kěnéng shèjí jiàgé huò shùjù xùnliàn tiáokuǎn. Quèrèn jí pīzhǔn xiǎnshì de jǐnggào, bìng fāsòng yí cì míngquè shěnyuè de xīn fēnpèi, fùgài xuǎnzé jǐnggào. Hermes bú huì jiāng cǐ fùgài bǎngdìng dào jǐnggào xiūdìng bǎnběn; tiáokuǎn biànhuà kěnéng xūyào chóngxīn shěnyuè."),
    HostMainWarningApprove("I approve the displayed host warning and the assignment effects above","我批准显示的主机警告及上述分配影响","Wǒ pīzhǔn xiǎnshì de zhǔjī jǐnggào jí shàngshù fēnpèi yǐngxiǎng"),
    HostMainAcknowledged("Host assignment acknowledged. Current reported configuration is shown separately; runtime and credential health remain unverified.","主机已确认分配。当前报告的配置单独显示；运行时与凭据健康状况仍未验证。","Zhǔjī yǐ quèrèn fēnpèi. Dāngqián bàogào de pèizhì dāndú xiǎnshì; yùnxíng shí yǔ píngjù jiànkāng zhuàngkuàng réng wèi yànzhèng."),
    HostMainProviderUnready("This provider is not reported authenticated. Configure it in Hermes and read the catalog again.","此提供方未报告已认证。请在 Hermes 中配置后重新读取目录。","Cǐ tígōng fāng wèi bàogào yǐ rènzhèng. Qǐng zài Hermes zhōng pèizhì hòu chóngxīn dúqǔ mùlù."),
    HostMainHostNotice("Host post-assignment notice","主机分配后的提示","Zhǔjī fēnpèi hòu de tíshì"),
    HostMainReceipt("The receipt records the requested and host-normalized pair, or a known warning refusal. It does not verify endpoint identity, credential validity, exact saved contents, causality or running-session adoption. Observe current configuration through a fresh read review.","回执记录请求及主机规范化后的组合，或已知警告拒绝。它不验证端点身份、凭据有效性、确切保存内容、因果关系或运行中会话的采用情况。请通过新的读取审阅查看当前配置。","Huízhí jìlù qǐngqiú jí zhǔjī guīfànhuà hòu de zǔhé, huò yǐzhī jǐnggào jùjué. Tā bù yànzhèng duāndiǎn shēnfèn, píngjù yǒuxiào xìng, quèqiè bǎocún nèiróng, yīnguǒ guānxì huò yùnxíng zhōng huìhuà de cǎiyòng qíngkuàng. Qǐng tōngguò xīn de dúqǔ shěnyuè chákàn dāngqián pèizhì."),
    HostModels("Host models and providers","主机模型与提供方","Zhǔjī móxíng yǔ tígōng fāng"),
    HostModelsRead("Read model configuration","读取模型配置","Dúqǔ móxíng pèizhì"),
    HostModelsRefresh("Refresh provider catalogs","刷新提供方目录","Shuāxīn tígōng fāng mùlù"),
    HostModelsBoundary("Host defaults and auxiliary tasks belong to this management profile. Phone chat selections and running sessions are separate.","主机默认模型和辅助任务属于此管理配置。手机聊天选择和运行中的会话是独立的。","Zhǔjī mòrèn móxíng hé fǔzhù rènwù shǔyú cǐ guǎnlǐ pèizhì. Shǒujī liáotiān xuǎnzé hé yùnxíng zhōng de huìhuà shì dúlì de."),
    HostModelsReadEffect("Reads reported main and auxiliary assignments, plugin task inheritance and provider catalogs for this profile. Hermes can probe the current custom endpoint, contact provider metadata or usage services, warm caches and persist discovered model lists. Secret values, endpoint addresses and raw warnings are discarded. Cancelling the phone wait cannot undo host probes or cache work. This does not test model execution or change assignments.","读取此配置报告的主模型、辅助任务、插件任务继承及提供方目录。Hermes 可能探测当前自定义端点，联系提供方元数据或用量服务，预热缓存并保存发现的模型列表。密钥值、端点地址和原始警告会被丢弃。取消手机等待无法撤销主机探测或缓存工作。这不会测试模型执行或更改分配。","Dúqǔ cǐ pèizhì bàogào de zhǔ móxíng, fǔzhù rènwù, chājiàn rènwù jìchéng jí tígōng fāng mùlù. Hermes kěnéng tàncè dāngqián zìdìngyì duāndiǎn, liánxì tígōng fāng yuán shùjù huò yòngliàng fúwù, yùrè huǎncún bìng bǎocún fāxiàn de móxíng lièbiǎo. Mìyuè zhí, duāndiǎn dìzhǐ hé yuánshǐ jǐnggào huì bèi diūqì. Qǔxiāo shǒujī děngdài wúfǎ chèxiāo zhǔjī tàncè huò huǎncún gōngzuò. Zhè bú huì cèshì móxíng zhíxíng huò gēnggǎi fēnpèi."),
    HostModelsRefreshEffect("Explicit refresh also clears model-list caches and can probe all saved custom endpoints. Provider failures may produce fallback catalog entries. Cancelling the phone wait cannot undo host probes or cache work.","明确刷新还会清除模型列表缓存，并可能探测所有保存的自定义端点。提供方失败时可能返回备用目录条目。取消手机等待无法撤销主机探测或缓存工作。","Míngquè shuāxīn hái huì qīngchú móxíng lièbiǎo huǎncún, bìng kěnéng tàncè suǒyǒu bǎocún de zìdìngyì duāndiǎn. Tígōng fāng shībài shí kěnéng fǎnhuí bèiyòng mùlù tiáomù. Qǔxiāo shǒujī děngdài wúfǎ chèxiāo zhǔjī tàncè huò huǎncún gōngzuò."),
    HostModelsSnapshot("Reported configuration and catalog snapshot; availability, authentication, price and runtime adoption remain unverified.","报告的配置与目录快照；可用性、认证、价格及运行时采用情况仍未验证。","Bàogào de pèizhì yǔ mùlù kuàizhào; kěyòng xìng, rènzhèng, jiàgé jí yùnxíng shí cǎiyòng qíngkuàng réng wèi yànzhèng."),
    HostModelsUnavailable("Model configuration is incomplete, inconsistent or unsupported. Review and read it again.","模型配置不完整、不一致或不受支持。请重新审阅并读取。","Móxíng pèizhì bù wánzhěng, bù yízhì huò bù shòu zhīchí. Qǐng chóngxīn shěnyuè bìng dúqǔ."),
    HostModelsMain("Configured main assignment","配置的主模型分配","Pèizhì de zhǔ móxíng fēnpèi"),
    HostModelsAuxiliary("Auxiliary task assignments","辅助任务分配","Fǔzhù rènwù fēnpèi"),
    HostModelsProviders("Reported providers","报告的提供方","Bàogào de tígōng fāng"),
    HostModelsFilter("Filter providers, models or tasks","筛选提供方、模型或任务","Shāixuǎn tígōng fāng, móxíng huò rènwù"),
    HostModelsReasoning("Reported reasoning effort","报告的推理强度","Bàogào de tuīlǐ qiángdù"),
    HostModelsInherited("Not reported; may inherit","未报告；可能继承","Wèi bàogào; kěnéng jìchéng"),
    HostModelsEndpoint("Custom endpoint configured; address hidden","已配置自定义端点；地址隐藏","Yǐ pèizhì zìdìngyì duāndiǎn; dìzhǐ yǐncáng"),
    HostModelsNoEndpoint("No reported endpoint override","未报告端点覆盖值","Wèi bàogào duāndiǎn fùgài zhí"),
    HostModelsLocal("Host reports a local endpoint","主机报告本地端点","Zhǔjī bàogào běndì duāndiǎn"),
    HostModelsInheritFrom("Inherits from task","继承自任务","Jìchéng zì rènwù"),
    HostModelsEffective("Reported effective inherited route","报告的有效继承路由","Bàogào de yǒuxiào jìchéng lùyóu"),
    HostModelsReportedAuth("Host authentication flag","主机认证标志","Zhǔjī rènzhèng biāozhì"),
    HostModelsAuthYes("Reported authenticated","报告已认证","Bàogào yǐ rènzhèng"),
    HostModelsAuthNo("Reported unauthenticated","报告未认证","Bàogào wèi rènzhèng"),
    HostModelsAuthUnknown("Not reported","未报告","Wèi bàogào"),
    HostModelsWarning("Host reported a warning; raw details are hidden","主机报告警告；原始详情隐藏","Zhǔjī bàogào jǐnggào; yuánshǐ xiángqíng yǐncáng"),
    HostModelsCatalog("Browse reported model IDs","浏览报告的模型标识","Liúlǎn bàogào de móxíng biāozhì"),
    HostModelsUnspecified("Not explicitly set","未明确设置","Wèi míngquè shèzhì"),
    HostEnvEmpty("Save an empty value","保存空值","Bǎocún kōng zhí"),
    HostEnvEmptyIntent("Explicitly store an empty string and keep this environment key","明确存储空字符串并保留此环境键","Míngquè cúnchǔ kōng zìfúchuàn bìng bǎoliú cǐ huánjìng jiàn"),
    HostEnvEmptyValue("Empty string: \"\"","空字符串：\"\"","Kōng zìfúchuàn: \"\""),
    HostEnvEmptyEffect("Stores an empty string in this profile environment and keeps the key. This route does not clear old value-matched credential mirrors for an empty replacement; existing pool credentials can remain, and environment-source suppression can be lifted. This is not credential removal or provider-side revocation. Reported absence cannot verify the exact empty value or runtime behavior.","在此配置环境中存储空字符串并保留键。空值替换时，此接口不会清除匹配旧值的凭据副本；现有凭据池条目可能保留，并可能解除环境来源的禁用。这不是凭据移除或提供方撤销。报告不存在无法验证确切空值或运行时行为。","Zài cǐ pèizhì huánjìng zhōng cúnchǔ kōng zìfúchuàn bìng bǎoliú jiàn. Kōng zhí tìhuàn shí, cǐ jiēkǒu bú huì qīngchú pǐpèi jiù zhí de píngjù fùběn; xiànyǒu píngjù chí tiáomù kěnéng bǎoliú, bìng kěnéng jiěchú huánjìng láiyuán de jìnyòng. Zhè bú shì píngjù yíchú huò tígōng fāng chèxiāo. Bàogào bù cúnzài wúfǎ yànzhèng quèqiè kōng zhí huò yùnxíng shí xíngwéi."),
    HostEnvironment("Host keys and environment","主机密钥与环境","Zhǔjī mìyuè yǔ huánjìng"),
    HostEnvRead("Read key metadata","读取密钥元数据","Dúqǔ mìyuè yuán shùjù"),
    HostEnvPrivacy("Reads variable names, reported presence and provider/tool metadata for this profile. Existing values and masked previews are discarded; no secret reveal or provider probe is requested. Typed replacements are temporary and never saved in receipts.","读取此配置的变量名、报告的存在状态及提供方和工具元数据。现有值与掩码预览会被丢弃，不请求密钥显示或提供方探测。输入的替换值仅临时保存，绝不写入回执。","Dúqǔ cǐ pèizhì de biànliàng míng, bàogào de cúnzài zhuàngtài jí tígōng fāng hé gōngjù yuán shùjù. Xiànyǒu zhí yǔ yǎnmǎ yùlǎn huì bèi diūqì, bù qǐngqiú mìyuè xiǎnshì huò tígōng fāng tàncè. Shūrù de tìhuàn zhí jǐn línshí bǎocún, jué bù xiěrù huízhí."),
    HostEnvFilter("Filter names or providers","筛选名称或提供方","Shāixuǎn míngchēng huò tígōng fāng"),
    HostEnvAdd("Add a key","添加密钥","Tiānjiā mìyuè"),
    HostEnvKey("Environment variable name","环境变量名","Huánjìng biànliàng míng"),
    HostEnvSet("Reported present in profile environment","报告在配置环境中存在","Bàogào zài pèizhì huánjìng zhōng cúnzài"),
    HostEnvUnset("Not reported present in profile environment","未报告在配置环境中存在","Wèi bàogào zài pèizhì huánjìng zhōng cúnzài"),
    HostEnvSave("Save or replace value","保存或替换值","Bǎocún huò tìhuàn zhí"),
    HostEnvRemove("Remove credential references","移除凭据引用","Yíchú píngjù yǐnyòng"),
    HostEnvFreshValue("Enter the complete new ASCII value. Nothing is prefilled. Hermes strips non-ASCII characters and line breaks, so the phone refuses them before sending.","请输入完整的 ASCII 新值，不会预填。Hermes 会剥除非 ASCII 字符和换行，因此手机会在发送前拒绝这些内容。","Qǐng shūrù wánzhěng de ASCII xīn zhí, bú huì yù tián. Hermes huì bōchú fēi ASCII zìfú hé huànháng, yīncǐ shǒujī huì zài fāsòng qián jùjué zhèxiē nèiróng."),
    HostEnvInvalid("Use a valid variable name and a nonempty printable ASCII value up to 16384 characters. Known execution/policy names and display-only masks cannot be saved. The host also enforces its current managed and dynamic launch policy.","请使用有效变量名及不超过 16384 字符的非空可打印 ASCII 值。不能保存已知执行和策略变量名或仅供显示的掩码。主机还会执行当前受管理策略和动态启动策略。","Qǐng shǐyòng yǒuxiào biànliàng míng jí bù chāoguò 16384 zìfú de fēi kōng kě dǎyìn ASCII zhí. Bù néng bǎocún yǐ zhī zhíxíng hé cèlüè biànliàng míng huò jǐn gōng xiǎnshì de yǎnmǎ. Zhǔjī hái huì zhíxíng dāngqián shòu guǎnlǐ cèlüè hé dòngtài qǐdòng cèlüè."),
    HostEnvProtected("This name is not writable through this editor. Existing keys can be reviewed for removal; host policy still applies.","此编辑器不可写入该名称。可以检查移除已有键，仍须遵守主机策略。","Cǐ biānjíqì bù kě xiěrù gāi míngchēng. Kěyǐ jiǎnchá yíchú yǐ yǒu jiàn, réng xū zūnshǒu zhǔjī cèlüè."),
    HostEnvChannel("Channel-managed variable: shared channel setup may need additional configuration.","通道管理的变量：共享通道设置可能还需其他配置。","Tōngdào guǎnlǐ de biànliàng: gòngxiǎng tōngdào shèzhì kěnéng hái xū qítā pèizhì."),
    HostEnvReview("Review environment change","检查环境更改","Jiǎnchá huánjìng gēnggǎi"),
    HostEnvSaveEffect("Writes this profile environment value, reconciles value-matched configuration credential mirrors and may re-enable/materialize environment-backed credential pools. Every plugin, provider or channel using this variable can be affected. No provider validation or plugin reconnect is requested.","写入此配置的环境值，协调值匹配的配置凭据副本，并可能重新启用或生成环境凭据池。使用此变量的所有插件、提供方或通道都可能受影响。不请求提供方验证或插件重连。","Xiěrù cǐ pèizhì de huánjìng zhí, xiétiáo zhí pǐpèi de pèizhì píngjù fùběn, bìng kěnéng chóngxīn qǐyòng huò shēngchéng huánjìng píngjù chí. Shǐyòng cǐ biànliàng de suǒyǒu chājiàn, tígōng fāng huò tōngdào dōu kěnéng shòu yǐngxiǎng. Bù qǐngqiú tígōng fāng yànzhèng huò chājiàn chónglián."),
    HostEnvRemoveEffect("Removes the environment entry and its environment-backed pool/model-cache references and value-matched configuration mirrors. Other OAuth/device/manual credentials can remain. This does not revoke credentials at the provider or stop active work. Missing environment presence does not exclude other references.","移除环境条目、环境凭据池和模型缓存引用，以及值匹配的配置副本。其他 OAuth、设备和手动凭据可能保留。这不会撤销提供方凭据或停止正在进行的工作。环境中未显示存在不代表没有其他引用。","Yíchú huánjìng tiáomù, huánjìng píngjù chí hé móxíng huǎncún yǐnyòng, yǐjí zhí pǐpèi de pèizhì fùběn. Qítā OAuth, shèbèi hé shǒudòng píngjù kěnéng bǎoliú. Zhè bú huì chèxiāo tígōng fāng píngjù huò tíngzhǐ zhèngzài jìnxíng de gōngzuò. Huánjìng zhōng wèi xiǎnshì cúnzài bù dàibiǎo méiyǒu qítā yǐnyòng."),
    HostEnvConcurrency("Fresh identity, profile home and reported metadata are checked before one send. The server has no revision guard and presence cannot detect a concurrent secret rotation. A lost or interrupted reply is uncertain and is never automatically repeated.","单次发送前会检查最新身份、配置目录和报告的元数据。服务器没有版本保护，存在状态也无法检测并发密钥轮换。丢失或中断回复的结果不确定，绝不会自动重复。","Dāncì fāsòng qián huì jiǎnchá zuìxīn shēnfèn, pèizhì mùlù hé bàogào de yuán shùjù. Fúwùqì méiyǒu bǎnběn bǎohù, cúnzài zhuàngtài yě wúfǎ jiǎncè bìngfā mìyuè lúnhuàn. Diūshī huò zhōngduàn huífù de jiéguǒ bù quèdìng, jué bú huì zìdòng chóngfù."),
    HostEnvApprove("Approve this one environment change","批准此次环境更改","Pīzhǔn cǐ cì huánjìng gēnggǎi"),
    HostEnvAcknowledged("Host acknowledged the environment change. Presence readback does not verify its exact value, provider validity, mirror cleanup or runtime adoption.","主机已确认环境更改。存在状态回读无法验证确切值、提供方有效性、副本清理或运行时采用。","Zhǔjī yǐ quèrèn huánjìng gēnggǎi. Cúnzài zhuàngtài huídú wúfǎ yànzhèng quèqiè zhí, tígōng fāng yǒuxiàoxìng, fùběn qīnglǐ huò yùnxíng shí cǎiyòng."),
    HostEnvReceipt("Receipts retain the variable name, operation, prior presence and public outcome counts. Values, masks, value hashes and mirror paths are never retained. Observation opens a new metadata-read review without mutation or secret reveal.","回执保留变量名、操作、之前的存在状态及公开结果计数。绝不保留值、掩码、值哈希或副本路径。观察会打开新的元数据读取检查，不进行更改或显示密钥。","Huízhí bǎoliú biànliàng míng, cāozuò, zhīqián de cúnzài zhuàngtài jí gōngkāi jiéguǒ jìshù. Jué bù bǎoliú zhí, yǎnmǎ, zhí hāxī huò fùběn lùjìng. Guānchá huì dǎkāi xīn de yuán shùjù dúqǔ jiǎnchá, bù jìnxíng gēnggǎi huò xiǎnshì mìyuè."),
    HostEnvUnavailable("Host environment metadata or verified profile-home support is unavailable. Refresh management or inspect the host.","主机环境元数据或已验证的配置目录支持不可用。请刷新管理或检查主机。","Zhǔjī huánjìng yuán shùjù huò yǐ yànzhèng de pèizhì mùlù zhīchí bù kěyòng. Qǐng shuāxīn guǎnlǐ huò jiǎnchá zhǔjī."),
    PluginSettings("Plugin settings","插件设置","Chājiàn shèzhì"),
    PluginSettingsRead("Read plugin settings","读取插件设置","Dúqǔ chājiàn shèzhì"),
    PluginSettingsPrivacy("This reads private host-reported setting values into temporary app memory. Details are hidden until shown. Closing or changing context clears them. Declared secrets have presence only.","这会将主机报告的私有设置值读取到应用临时内存中。详情默认隐藏，关闭或切换上下文后清除。声明的密钥仅显示是否存在。","Zhè huì jiāng zhǔjī bàogào de sīyǒu shèzhì zhí dúqǔ dào yìngyòng línshí nèicún zhōng. Xiángqíng mòrèn yǐncáng, guānbì huò qiēhuàn shàngxiàwén hòu qīngchú. Shēngmíng de mìyuè jǐn xiǎnshì shìfǒu cúnzài."),
    PluginSettingsUnavailable("Settings are unavailable without a supported canonical plugin, bounded declared fields and verified profile home. Refresh or inspect the host.","没有受支持的规范插件、大小受限的声明字段和已验证的配置目录时，设置不可用。请刷新或检查主机。","Méiyǒu shòu zhīchí de guīfàn chājiàn, dàxiǎo shòu xiàn de shēngmíng zìduàn hé yǐ yànzhèng de pèizhì mùlù shí, shèzhì bù kěyòng. Qǐng shuāxīn huò jiǎnchá zhǔjī."),
    PluginSettingsEmpty("The host reports no declared settings.","主机未报告声明的设置。","Zhǔjī wèi bàogào shēngmíng de shèzhì."),
    PluginSettingsReported("Host-reported value","主机报告值","Zhǔjī bàogào zhí"),
    PluginSettingsDefault("Declared default","声明的默认值","Shēngmíng de mòrèn zhí"),
    PluginSettingsSecret("Declared secrets use the separate Host keys and environment review. They are never written as plugin settings.","声明的密钥使用单独的主机密钥与环境检查，绝不作为插件设置写入。","Shēngmíng de mìyuè shǐyòng dāndú de zhǔjī mìyuè yǔ huánjìng jiǎnchá, jué bù zuòwéi chājiàn shèzhì xiěrù."),
    PluginSettingsNested("This dotted key is written as a nested setting. The current host listing can report its default instead of its stored nested value, so the app cannot verify it by readback.","此点分键会写入嵌套设置。当前主机列表可能返回默认值而非已存储的嵌套值，因此应用无法通过回读验证。","Cǐ diǎn fēn jiàn huì xiěrù qiàntào shèzhì. Dāngqián zhǔjī lièbiǎo kěnéng fǎnhuí mòrèn zhí ér fēi yǐ cúnchǔ de qiàntào zhí, yīncǐ yìngyòng wúfǎ tōngguò huídú yànzhèng."),
    PluginSettingsEdit("Edit setting","编辑设置","Biānjí shèzhì"),
    PluginSettingsValue("New value","新值","Xīn zhí"),
    PluginSettingsRequired("Declared required by this plugin","此插件声明为必填项","Cǐ chājiàn shēngmíng wéi bì tián xiàng"),
    PluginSettingsInvalid("Enter the declared type: text, a finite number, true/false, a listed choice, or a JSON object/array. Null and secret values cannot be saved here.","请输入声明的类型：文本、有限数字、true/false、列出的选项或 JSON 对象/数组。此处不能保存 null 或密钥值。","Qǐng shūrù shēngmíng de lèixíng: wénběn, yǒuxiàn shùzì, true/false, liè chū de xuǎnxiàng huò JSON duìxiàng/shùzǔ. Cǐchù bù néng bǎocún null huò mìyuè zhí."),
    PluginSettingsReview("Review setting change","检查设置更改","Jiǎnchá shèzhì gēnggǎi"),
    PluginSettingsEffect("Saves one declared non-secret value on this host profile. Hermes enforces managed-key policy, notifies plugin listeners and may reconnect affected MCP servers or start their processes. A save does not prove runtime adoption or health.","在此主机配置中保存一个声明的非密钥值。Hermes 会执行受管理键策略、通知插件监听器，并可能重连受影响的 MCP 服务或启动其进程。保存不代表运行时已采用或健康。","Zài cǐ zhǔjī pèizhì zhōng bǎocún yí gè shēngmíng de fēi mìyuè zhí. Hermes huì zhíxíng shòu guǎnlǐ jiàn cèlüè, tōngzhī chājiàn jiāntīngqì, bìng kěnéng chónglián shòu yǐngxiǎng de MCP fúwù huò qǐdòng qí jìnchéng. Bǎocún bù dàibiǎo yùnxíng shí yǐ cǎiyòng huò jiànkāng."),
    PluginSettingsLimit("The app checks fresh metadata and reported settings before sending once. The server has no revision guard; concurrent host edits can still change the target or overwrite this value. A lost reply is uncertain and is never automatically repeated.","应用会在单次发送前检查最新元数据和报告的设置。服务器没有版本保护，并发主机编辑仍可能改变目标或覆盖此值。丢失回复的结果不确定，绝不会自动重复。","Yìngyòng huì zài dāncì fāsòng qián jiǎnchá zuìxīn yuán shùjù hé bàogào de shèzhì. Fúwùqì méiyǒu bǎnběn bǎohù, bìngfā zhǔjī biānjí réng kěnéng gǎibiàn mùbiāo huò fùgài cǐ zhí. Diūshī huífù de jiéguǒ bù quèdìng, jué bú huì zìdòng chóngfù."),
    PluginSettingsApprove("Approve saving this displayed value once","批准单次保存此显示值","Pīzhǔn dāncì bǎocún cǐ xiǎnshì zhí"),
    PluginSettingsSaved("Host acknowledged the setting save. Readback and runtime adoption are separate.","主机已确认保存设置。回读与运行时采用是独立结果。","Zhǔjī yǐ quèrèn bǎocún shèzhì. Huídú yǔ yùnxíng shí cǎiyòng shì dúlì jiéguǒ."),
    PluginSettingsObservation("Receipts retain the key/type and outcome, never setting values or hashes. Read current configuration opens a separate plugin review; reading settings then requires its own review.","回执保留键、类型和结果，绝不保留设置值或其哈希。读取当前配置会打开单独的插件检查，随后读取设置还需另行检查。","Huízhí bǎoliú jiàn, lèixíng hé jiéguǒ, jué bù bǎoliú shèzhì zhí huò qí hāxī. Dúqǔ dāngqián pèizhì huì dǎkāi dāndú de chājiàn jiǎnchá, suíhòu dúqǔ shèzhì hái xū lìngxíng jiǎnchá."),
    ReviewSharedImages("Review shared images","检查共享图片","Jiǎnchá gòngxiǎng túpiàn"),
    InvalidImageShare("Share up to three images using temporary content-URI access. This share cannot be imported.","请通过临时内容 URI 访问权限共享最多三张图片。无法导入此次共享。","Qǐng tōngguò línshí nèiróng URI fǎngwèn quánxiàn gòngxiǎng zuì duō sān zhāng túpiàn. Wúfǎ dǎorù cǐ cì gòngxiǎng."),
    SharedImageInfo("These images replace the image selection in the current draft. Shared text is appended. Sending remains a separate action.","这些图片将替换当前草稿中的图片选择。共享文字会追加到草稿中。发送仍需单独操作。","Zhèxiē túpiàn jiāng tìhuàn dāngqián cǎogǎo zhōng de túpiàn xuǎnzé. Gòngxiǎng wénzì huì zhuījiā dào cǎogǎo zhōng. Fāsòng réng xū dāndú cāozuò."),
    SharedCaption("Shared text","共享文字","Gòngxiǎng wénzì"),
    WaitForImageTarget("Finish the current operation before importing these images.","请先完成当前操作，再导入这些图片。","Qǐng xiān wánchéng dāngqián cāozuò, zài dǎorù zhèxiē túpiàn."),
    UseSharedImages("Use images in this draft","在此草稿中使用图片","Zài cǐ cǎogǎo zhōng shǐyòng túpiàn"),
    ChooseImages("Choose images","选择图片","Xuǎnzé túpiàn"),
    ImageMessage("Image message","图片消息","Túpiàn xiāoxi"),
    RemoveImage("Remove image","移除图片","Yíchú túpiàn"),
    LoadingImages("Preparing private image previews…","正在准备私有图片预览…","Zhèngzài zhǔnbèi sīyǒu túpiàn yùlǎn…"),
    ImageContextChanged("The connection or conversation changed. Choose the images again for the current draft.","连接或对话已更改。请为当前草稿重新选择图片。","Liánjiē huò duìhuà yǐ gēnggǎi. Qǐng wèi dāngqián cǎogǎo chóngxīn xuǎnzé túpiàn."),
    ImageInputLimit("Choose at most three images.","最多选择三张图片。","Zuì duō xuǎnzé sān zhāng túpiàn."),
    ImageImportFailed("Images could not be prepared. Choose up to three raster images under 8 MB each, and check that access is still available.","无法准备图片。请选择最多三张、每张小于 8 MB 的位图，并检查是否仍有访问权限。","Wúfǎ zhǔnbèi túpiàn. Qǐng xuǎnzé zuì duō sān zhāng, měi zhāng xiǎo yú 8 MB de wèitú, bìng jiǎnchá shìfǒu réng yǒu fǎngwèn quánxiàn."),
    ImagePickerUnavailable("No compatible photo or document picker is available on this device.","本机上没有兼容的照片或文档选择器。","Běnjī shàng méiyǒu jiānróng de zhàopiàn huò wéndàng xuǎnzéqì."),
    ImageInputInfo("Choose up to three images, each under 8 MB. The app keeps resized JPEG copies without source metadata. Review the previews; Send submits them to Hermes. Your selected server/model must support images. Image drafts are cleared when you change connection/conversation or restart the app.","最多选择三张图片，每张小于 8 MB。应用会保存不含原始元数据的缩放 JPEG 副本。请检查预览，点击发送后才提交给 Hermes。所选服务器和模型必须支持图片。切换连接、对话或重启应用会清除图片草稿。","Zuì duō xuǎnzé sān zhāng túpiàn, měi zhāng xiǎo yú 8 MB. Yìngyòng huì bǎocún bù hán yuánshǐ yuán shùjù de suōfàng JPEG fùběn. Qǐng jiǎnchá yùlǎn, diǎnjī fāsòng hòu cái tíjiāo gěi Hermes. Suǒ xuǎn fúwùqì hé móxíng bìxū zhīchí túpiàn. Qiēhuàn liánjiē, duìhuà huò chóngqǐ yìngyòng huì qīngchú túpiàn cǎogǎo."),
    EnlargeImage("Enlarge image","放大图片","Fàngdà túpiàn"),
    ImageCacheMissing("The cached image is missing or unreadable.","缓存图片丢失或无法读取。","Huǎncún túpiàn diūshī huò wúfǎ dúqǔ."),
    ImageOpenFailed("No browser could open this image.","没有浏览器可以打开此图片。","Méiyǒu liúlǎnqì kěyǐ dǎkāi cǐ túpiàn."),
    ImagePreview("Image preview","图片预览","Túpiàn yùlǎn"),
    ImageUnavailable("This image is unavailable on this device. Host files and unsupported image formats have no supported mobile download route.","此图片在本机上不可用。主机文件和不支持的图片格式没有可用的移动端下载接口。","Cǐ túpiàn zài běnjī shàng bù kěyòng. Zhǔjī wénjiàn hé bù zhīchí de túpiàn géshì méiyǒu kěyòng de yídòngduān xiàzài jiēkǒu."),
    RemoteImage("Remote image","远程图片","Yuǎnchéng túpiàn"),
    RemoteImageInfo("Opening this image contacts its host in your browser. The app does not attach your Hermes bearer token.","打开此图片会在浏览器中访问图片主机。应用不会附加 Hermes 访问令牌。","Dǎkāi cǐ túpiàn huì zài liúlǎnqì zhōng fǎngwèn túpiàn zhǔjī. Yìngyòng bú huì fùjiā Hermes fǎngwèn lìngpái."),
    OpenImageBrowser("Open image in browser","在浏览器中打开图片","Zài liúlǎnqì zhōng dǎkāi túpiàn"),
    AccountingHistoryInfo("Recent accounting for this conversation, up to 100 runs or local turns. These records survive server history refresh. A local turn ID does not establish a native run identity.","此对话最近的用量记录，最多显示 100 个运行或本地请求。这些记录在刷新服务器历史后仍保留。本地请求标识不代表原生运行身份。","Cǐ duìhuà zuìjìn de yòngliàng jìlù, zuì duō xiǎnshì yì bǎi gè yùnxíng huò běndì qǐngqiú. Zhèxiē jìlù zài shuāxīn fúwùqì lìshǐ hòu réng bǎoliú. Běndì qǐngqiú biāozhì bù dàibiǎo yuánshēng yùnxíng shēnfèn."),
    RuntimeUsage("Runtime and usage","运行模型与用量","Yùnxíng móxíng yǔ yòngliàng"),
    RuntimeUsageInfo("Hermes supplied these values. Counters may cover the session; missing values are unknown. These values do not establish your provider invoice.","这些值由 Hermes 提供。计数可能涵盖整个会话，缺失值表示未知。这些值不代表提供商账单。","Zhèxiē zhí yóu Hermes tígōng. Jìshù kěnéng hángài zhěnggè huìhuà, quēshī zhí biǎoshì wèizhī. Zhèxiē zhí bù dàibiǎo tígōngshāng zhàngdān."),
    ServedRuntime("Server-reported runtime","服务器报告的运行模型","Fúwùqì bàogào de yùnxíng móxíng"),
    RecentActivityInfo("Recent server activity, up to 200 events. Matching call IDs are grouped within the same run and execution generation. Events without IDs remain separate. Only public activity fields are shown.","最近的服务器活动，最多显示 200 个事件。同一运行和执行代次中匹配的调用标识会分组，无标识的事件保持独立。仅显示公开活动字段。","Zuìjìn de fúwùqì huódòng, zuì duō xiǎnshì èr bǎi gè shìjiàn. Tóng yī yùnxíng hé zhíxíng dàicì zhōng pǐpèi de diàoyòng biāozhì huì fēnzǔ, wú biāozhì de shìjiàn bǎochí dúlì. Jǐn xiǎnshì gōngkāi huódòng zìduàn."),
    InputTokens("Input tokens","输入令牌","Shūrù lìngpái"),
    OutputTokens("Output tokens","输出令牌","Shūchū lìngpái"),
    TotalTokens("Total tokens","总令牌","Zǒng lìngpái"),
    CacheReadTokens("Cache-read tokens","缓存读取令牌","Huǎncún dúqǔ lìngpái"),
    CacheWriteTokens("Cache-write tokens","缓存写入令牌","Huǎncún xiěrù lìngpái"),
    ReasoningTokens("Reasoning token count","推理令牌计数","Tuīlǐ lìngpái jìshù"),
    RouteSource("Runtime route source","运行路由来源","Yùnxíng lùyóu láiyuán"),
    Subagent("Subagent activity","子代理活动","Zǐ dàilǐ huódòng"),
    ActivityIdentity("Activity call ID","活动调用标识","Huódòng diàoyòng biāozhì"),
    AgentIdentity("Subagent ID","子代理标识","Zǐ dàilǐ biāozhì"),
    ChildSession("Child session ID","子会话标识","Zǐ huìhuà biāozhì"),
    DelegationIdentity("Delegation ID","委派标识","Wěipài biāozhì"),
    ParentIdentity("Parent ID","父级标识","Fùjí biāozhì"),
    AgentGoal("Delegated goal","委派目标","Wěipài mùbiāo"),
    AgentSummary("Server summary","服务器摘要","Fúwùqì zhāiyào"),
    AgentOutput("Public output excerpt","公开输出节选","Gōngkāi shūchū jiéxuǎn"),
    ReportedCost("Server-reported cost (USD)","服务器报告的费用（美元）","Fúwùqì bàogào de fèiyòng (měiyuán)"),
    DurationSeconds("Duration (seconds)","耗时（秒）","Hàoshí (miǎo)"),
    FilesRead("Files read","读取的文件","Dúqǔ de wénjiàn"),
    FilesWritten("Files written","写入的文件","Xiěrù de wénjiàn"),
    ApiCalls("API calls","API 调用次数","API diàoyòng cìshù"),
    ToolCount("Tool count","工具计数","Gōngjù jìshù"),
    AgentDepth("Delegation depth","委派深度","Wěipài shēndù"),
    TaskIndex("Task index","任务序号","Rènwù xùhào"),
    TaskCount("Task count","任务计数","Rènwù jìshù"),
    ServerValue("Server value","服务器值","Fúwùqì zhí"),
    LocalNetworkInfo("Android 17 requires permission to reach a Hermes server on your LAN or private VPN. Public internet connections do not need this permission. After granting it, connect or check the run status again.","Android 17 需要权限才能访问局域网或专用 VPN 上的 Hermes 服务器。公共互联网连接不需要此权限。授权后，请重新连接或检查运行状态。","Android 17 xūyào quánxiàn cái néng fǎngwèn júyùwǎng huò zhuānyòng VPN shàng de Hermes fúwùqì. Gōnggòng hùliánwǎng liánjiē bù xūyào cǐ quánxiàn. Shòuquán hòu, qǐng chóngxīn liánjiē huò jiǎnchá yùnxíng zhuàngtài."),
    LocalNetworkAllow("Allow local network access","允许本地网络访问","Yǔnxǔ běndì wǎngluò fǎngwèn"),
