    SkillLockUnknown("Curator edit lock: unknown","整理器编辑锁：未知","Zhěnglǐqì biānjí suǒ: wèizhī"),
    SkillUnsupported("The host did not report a typed state for this control. Refresh or use the Hermes dashboard.","主机未报告此控件的明确状态。请刷新或使用 Hermes 控制台。","Zhǔjī wèi bàogào cǐ kòngjiàn de míngquè zhuàngtài. Qǐng shuāxīn huò shǐyòng Hermes kòngzhìtái."),
    SkillToggleEffect("Changes profile skill availability for future prompt loading. It does not uninstall files, revoke tool access or stop existing work.","更改此配置后续提示加载的技能可用性。不会卸载文件、撤销工具权限或停止现有工作。","Gēnggǎi cǐ pèizhì hòuxù tíshì jiāzài de jìnéng kěyòngxìng. Bú huì xièzài wénjiàn, chèxiāo gōngjù quánxiàn huò tíngzhǐ xiànyǒu gōngzuò."),
    SkillLockEffect("Sets the host curator/background-review edit lock. Your own edits remain allowed. This is not a general file permission, skill disable or tool-access restriction.","设置主机整理器和后台审阅的编辑锁。您自己的编辑仍被允许。这不是通用文件权限，不会禁用技能或限制工具访问。","Shèzhì zhǔjī zhěnglǐqì hé hòutái shěnyuè de biānjí suǒ. Nín zìjǐ de biānjí réng bèi yǔnxǔ. Zhè bú shì tōngyòng wénjiàn quánxiàn, bú huì jìnyòng jìnéng huò xiànzhì gōngjù fǎngwèn."),
    SkillChanged("Skill configuration acknowledged and observed. Existing work may continue.","技能配置已确认并读取验证。现有工作可能继续。","Jìnéng pèizhì yǐ quèrèn bìng dúqǔ yànzhèng. Xiànyǒu gōngzuò kěnéng jìxù."),
    GatewayAutomation("Gateway schedules","网关计划","Wǎngguān jìhuà"),
    GatewayLoad("Read gateway schedules","读取网关计划","Dúqǔ wǎngguān jìhuà"),
    GatewayConnectionEffect("Opens the dashboard gateway connection for this profile. Connecting may initialize configured MCP host processes. Reads include paused schedules; they do not submit an agent turn or change a schedule.","为此配置打开控制台网关连接。连接可能初始化已配置的 MCP 主机进程。读取包括已暂停的计划；不会提交智能体回合或更改计划。","Wèi cǐ pèizhì dǎkāi kòngzhìtái wǎngguān liánjiē. Liánjiē kěnéng chūshǐhuà yǐ pèizhì de MCP zhǔjī jìnchéng. Dúqǔ bāokuò yǐ zàntíng de jìhuà; bú huì tíjiāo zhìnéngtǐ huíhé huò gēnggǎi jìhuà."),
    GatewayScopeUnsupported("The gateway did not prove this explicit profile scope or returned an unsupported contract. Use the Hermes dashboard.","网关未证明此明确配置范围，或返回了不支持的协议。请使用 Hermes 控制台。","Wǎngguān wèi zhèngmíng cǐ míngquè pèizhì fànwéi, huò fǎnhuí le bù zhīchí de xiéyì. Qǐng shǐyòng Hermes kòngzhìtái."),
    GatewaySchedulerReported("Host reports the scheduler gateway is running. This does not prove a job ran.","主机报告调度网关正在运行。这不能证明任务已运行。","Zhǔjī bàogào diàodù wǎngguān zhèngzài yùnxíng. Zhè bù néng zhèngmíng rènwù yǐ yùnxíng."),
    GatewaySchedulerUnavailable("Host reports no running scheduler gateway. Saved schedules may not fire.","主机报告没有运行中的调度网关。已保存的计划可能不会触发。","Zhǔjī bàogào méiyǒu yùnxíng zhōng de diàodù wǎngguān. Yǐ bǎocún de jìhuà kěnéng bú huì chùfā."),
    GatewaySchedulerUnknown("Scheduler gateway readiness was not established.","尚未确定调度网关是否就绪。","Shàngwèi quèdìng diàodù wǎngguān shìfǒu jiùxù."),
    GatewayPromptPreview("Prompt preview reported by the gateway","网关报告的提示预览","Wǎngguān bàogào de tíshì yùlǎn"),
    GatewayCronPause("Pause gateway schedule","暂停网关计划","Zàntíng wǎngguān jìhuà"),
    GatewayCronResume("Resume gateway schedule","恢复网关计划","Huīfù wǎngguān jìhuà"),
    GatewayCronDelete("Remove gateway schedule and outputs","移除网关计划及输出","Yíchú wǎngguān jìhuà jí shūchū"),
    GatewaySelectorCollision("Another job name matches this ID. Rename that job on the host before using these controls.","另一个任务名称与此 ID 相同。请先在主机上重命名该任务，再使用这些控件。","Lìng yí gè rènwù míngchēng yǔ cǐ ID xiāngtóng. Qǐng xiān zài zhǔjī shàng chóngmìngmíng gāi rènwù, zài shǐyòng zhèxiē kòngjiàn."),
    GatewayControlStateUnknown("Pause/resume is unavailable without a known enabled or paused state. Refresh or use the host dashboard.","没有明确的启用或暂停状态时，无法暂停或恢复。请刷新或使用主机控制台。","Méiyǒu míngquè de qǐyòng huò zàntíng zhuàngtài shí, wúfǎ zàntíng huò huīfù. Qǐng shuāxīn huò shǐyòng zhǔjī kòngzhìtái."),
    GatewayCronAccepted("Host acknowledged the schedule request. Read configuration separately to inspect its state.","主机已确认计划请求。请另行读取配置以检查状态。","Zhǔjī yǐ quèrèn jìhuà qǐngqiú. Qǐng lìngxíng dúqǔ pèizhì yǐ jiǎnchá zhuàngtài."),
    GatewayCronChanged("Schedule change acknowledged and observed. Execution outcome is separate.","计划更改已确认并读取验证。执行结果另行确定。","Jìhuà gēnggǎi yǐ quèrèn bìng dúqǔ yànzhèng. Zhíxíng jiéguǒ lìngxíng quèdìng."),
    GatewayReasoning("Configured reasoning effort","已配置的推理强度","Yǐ pèizhì de tuīlǐ qiángdù"),
    GatewayMonitorScript("Host monitor script","主机监控脚本","Zhǔjī jiānkòng jiǎoběn"),
    GatewayMonitorUrl("Host monitor URL","主机监控网址","Zhǔjī jiānkòng wǎngzhǐ"),
    GatewayInterpreter("Host script interpreter","主机脚本解释器","Zhǔjī jiǎoběn jiěshìqì"),
    GatewayAttach("Attach to a host session (reported)","附加到主机会话（主机报告）","Fùjiā dào zhǔjī huìhuà (zhǔjī bàogào)"),
    GatewayPinned("Pinned runtime (reported)","固定运行配置（主机报告）","Gùdìng yùnxíng pèizhì (zhǔjī bàogào)"),
    GatewayToolsetsUnreported("The gateway omitted the toolset allowlist. Omission does not distinguish inherited settings from an empty allowlist; inspect Advanced schedules for full configuration.","网关未报告工具集允许列表。省略字段无法区分继承设置与空允许列表；请在高级计划中检查完整配置。","Wǎngguān wèi bàogào gōngjùjí yǔnxǔ lièbiǎo. Shěnglüè zìduàn wúfǎ qūfēn jìchéng shèzhì yǔ kōng yǔnxǔ lièbiǎo; qǐng zài gāojí jìhuà zhōng jiǎnchá wánzhěng pèizhì."),
    GatewayPauseEffect("Pauses future scheduling. A current run may continue; this does not request its cancellation.","暂停后续调度。当前运行可能继续；这不会请求取消当前运行。","Zàntíng hòuxù diàodù. Dāngqián yùnxíng kěnéng jìxù; zhè bú huì qǐngqiú qǔxiāo dāngqián yùnxíng."),
    GatewayResumeEffect("Activates the saved host job, including its script, provider, tools and delivery. An overdue recurring slot can fire under host catch-up policy. This does not prove readiness or successful execution.","激活主机保存的任务，包括脚本、提供方、工具及投递。过期的重复时间点可能按主机补跑策略触发。这不能证明已就绪或执行成功。","Jīhuó zhǔjī bǎocún de rènwù, bāokuò jiǎoběn, tígōngfāng, gōngjù jí tóudì. Guòqī de chóngfù shíjiān diǎn kěnéng àn zhǔjī bǔpǎo cèlüè chùfā. Zhè bù néng zhèngmíng yǐ jiùxù huò zhíxíng chénggōng."),
    GatewayDeleteEffect("Deletes the saved schedule, its stored output directory and notepad, and requests cooperative cancellation of its current run. Deleted outputs cannot be restored here. Acknowledgement does not prove the run has stopped.","删除已保存的计划、输出目录和记事本，并请求协作式取消当前运行。无法在此恢复已删除的输出。确认不代表运行已停止。","Shānchú yǐ bǎocún de jìhuà, shūchū mùlù hé jìshìběn, bìng qǐngqiú xiézuò shì qǔxiāo dāngqián yùnxíng. Wúfǎ zài cǐ huīfù yǐ shānchú de shūchū. Quèrèn bù dàibiǎo yùnxíng yǐ tíngzhǐ."),
    GatewayMutationConnection("The gateway connection may initialize configured MCP processes. This confirms one requested schedule action; it is never retried automatically.","网关连接可能初始化已配置的 MCP 进程。此操作仅确认一次计划更改请求；不会自动重试。","Wǎngguān liánjiē kěnéng chūshǐhuà yǐ pèizhì de MCP jìnchéng. Cǐ cāozuò jǐn quèrèn yí cì jìhuà gēnggǎi qǐngqiú; bú huì zìdòng chóngshì."),
    GatewayMutationRace("Hermes resolves this ID first, then a matching name if the ID is gone. The app checks current configuration and known collisions, but the host has no revision check preventing concurrent external edits.","Hermes 先按此 ID 查找；若 ID 不存在，则按匹配名称查找。应用会检查当前配置和已知冲突，但主机没有可阻止外部并发编辑的版本检查。","Hermes xiān àn cǐ ID cházhǎo; ruò ID bù cúnzài, zé àn pǐpèi míngchēng cházhǎo. Yìngyòng huì jiǎnchá dāngqián pèizhì hé yǐzhī chōngtū, dàn zhǔjī méiyǒu kě zǔzhǐ wàibù bìngfā biānjí de bǎnběn jiǎnchá."),
    GatewayReceiptEffect("Read current configuration for an observation. This receipt is not a run-completion or cancellation-completion report.","读取当前配置以观察状态。此回执不是运行完成或取消完成的报告。","Dúqǔ dāngqián pèizhì yǐ guānchá zhuàngtài. Cǐ huízhí bú shì yùnxíng wánchéng huò qǔxiāo wánchéng de bàogào."),
    PluginConnectionEffect("Opens the dashboard gateway connection for this profile. Connecting may initialize configured MCP host processes.", "为此配置打开控制台网关连接。连接可能初始化已配置的 MCP 主机进程。", "Wèi cǐ pèizhì dǎkāi kòngzhìtái wǎngguān liánjiē. Liánjiē kěnéng chūshǐhuà yǐ pèizhì de MCP zhǔjī jìnchéng."),
    PluginUpdate("Review plugin update", "审核插件更新", "shěn hé chā jiàn gēng xīn"),
    PluginUpdateUnsupported("Update needs a verified user/git directory, no known target collision, and a reported catalog pin for catalog installs. Custom commit-pinned installs require an explicit host reinstall.", "更新需要已验证的用户／Git 目录、无已知目标冲突，以及目录安装报告的固定版本。自定义提交固定安装需要在主机明确重新安装。", "gēng xīn xū yào yǐ yàn zhèng de yòng hù／Git mù lù、wú yǐ zhī mù biāo chōng tū hé bào gào de gù dìng bǎn běn。"),
    PluginUpdateEffect("Updates host plugin code and can change dependencies in the shared host environment, activate features and rename a catalog install. Catalog updates can back up tracked local edits and carry untracked files; Git/subdirectory updates can re-clone or stage local changes. The app first sends both grant flags false. Hermes can auto-accept caution for catalog pins it treats as reviewed, and host configuration can disable scanning. These flags do not bypass dependency-admission or provenance restrictions. Live, deferred and restart reports remain separate.", "更新主机插件代码，可能更改共享主机环境的依赖、激活功能和重命名目录安装。目录更新可备份已跟踪的本地编辑并保留未跟踪文件；Git／子目录更新可重新克隆或暂存本地更改。应用首次发送的两个授权标志均为否。Hermes 可为视为已审核的目录版本自动接受警告，且主机配置可禁用扫描。这些标志不会绕过依赖准入或来源限制。即时、延后和重启报告仍然独立。", "gēng xīn zhǔ jī chā jiàn dài mǎ，kě néng gēng gǎi yī lài、jī huó gōng néng hé chóng mìng míng ān zhuāng。yìng yòng shǒu cì fā sòng de liǎng gè shòu quán biāo zhì jūn wéi fǒu。Hermes kě wèi yǐ shěn hé bǎn běn zì dòng jiē shòu jǐng gào，zhǔ jī yě kě jìn yòng sǎo miáo。"),
    PluginUpdateLimit("The app rechecks profile mapping, inventory and the reported catalog pin before one request. Hermes resolves the source and applies its current scan policy again. This update RPC has no expected revision or proposal ID; concurrent catalog/source changes can alter the update or findings after review. No inspected-commit guard is sent. A ten-minute reply wait or cancellation does not stop host work. Lost replies are uncertain and never automatically repeated.", "应用会在一次请求前重新检查配置映射、清单和报告的目录版本。Hermes 会再次解析来源并应用其当前扫描策略。此更新 RPC 没有预期版本或提案标识；并发目录／来源更改可在审核后改变更新或发现。不会发送已检查提交保护。十分钟回复等待或取消不会停止主机工作。丢失回复是不确定结果，绝不自动重复。", "yìng yòng huì zài yī cì qǐng qiú qián chóng xīn jiǎn chá pèi zhì、qīng dān hé bǎn běn。bìng fā gēng gǎi kě zài shěn hé hòu gǎi biàn gēng xīn。diū shī huí fù jué bù zì dòng chóng fù。"),
    PluginUpdateCapabilities("Host requests capability approval", "主机请求权限批准", "zhǔ jī qǐng qiú quán xiàn pī zhǔn"),
    PluginUpdateScan("Host scan blocked publication", "主机扫描阻止发布", "zhǔ jī sǎo miáo zǔ zhǐ fā bù"),
    PluginUpdateProposalPin("Host-reported catalog proposal pin", "主机报告的目录提案版本", "zhǔ jī bào gào de mù lù tí àn bǎn běn"),
    PluginUpdateReportedPin("Host-reported result pin", "主机报告的结果版本", "zhǔ jī bào gào de jié guǒ bǎn běn"),
    PluginUpdateHiddenDetails("Sensitive declared reference hidden", "已隐藏敏感声明引用", "yǐ yǐn cáng mǐn gǎn shēng míng yǐn yòng"),
    PluginUpdateShowDetails("Show declared details (may include private references)", "显示声明详情（可能包含私密引用）", "xiǎn shì shēng míng xiáng qíng（kě néng bāo hán sī mì yǐn yòng）"),
    PluginUpdateHideDetails("Hide declared details", "隐藏声明详情", "yǐn cáng shēng míng xiáng qíng"),
    PluginUpdateNoPublication("The host refused plugin publication. Cloning, scanning or backups may already have occurred. A further attempt needs a new review; it is not sent automatically.", "主机已拒绝插件发布。克隆、扫描或备份可能已经发生。进一步尝试需要新的审核，不会自动发送。", "zhǔ jī yǐ jù jué chā jiàn fā bù。kè lóng、sǎo miáo huò bèi fèn kě néng yǐ jīng fā shēng。jìn yī bù cháng shì xū yào xīn de shěn hé。"),
    PluginUpdateReviewDecision("Review another update attempt", "审核另一次更新尝试", "shěn hé lìng yī cì gēng xīn cháng shì"),
    PluginUpdateDangerous("Dangerous scan verdicts cannot be overridden.", "危险扫描结论不能绕过。", "wēi xiǎn sǎo miáo jié lùn bù néng rào guò。"),
    PluginUpdateCatalogScanLimit("Catalog scanning follows the host's reviewed-pin policy; this update RPC does not forward a catalog caution override. Inspect this response on the host.", "目录扫描遵循主机的已审核版本策略；此更新 RPC 不会转发目录警告覆盖。请在主机检查此回复。", "mù lù sǎo miáo zūn xún zhǔ jī de yǐ shěn hé bǎn běn cè lüè。cǐ RPC bú huì zhuǎn fā mù lù jǐng gào fù gài。qǐng zài zhǔ jī jiǎn chá。"),
    PluginUpdateDecisionUnavailable("This response is incomplete, changed or expired. Refresh and request a new update review, or inspect it on the host.", "此回复不完整、已更改或已过期。请刷新并请求新的更新审核，或在主机检查。", "cǐ huí fù bù wán zhěng、yǐ gēng gǎi huò yǐ guò qī。qǐng shuā xīn bìng qǐng qiú xīn de shěn hé。"),
    PluginUpdateCapabilityGrant("Approves capability widening for the host's next resolved catalog update, including dependency, OAuth and desktop additions shown here. The server does not bind this flag to the displayed proposal pin or delta; concurrent catalog changes can widen the next proposal differently.", "批准主机下一次解析的目录更新扩大权限，包括此处显示的依赖、OAuth 和桌面新增项。服务器不会将此标志绑定到显示的提案版本或差异；并发目录更改可能以不同方式扩大下一提案。", "pī zhǔn zhǔ jī xià yī cì mù lù gēng xīn kuò dà quán xiàn。fú wù qì bú huì jiāng cǐ biāo zhì bǎng dìng dào xiǎn shì de tí àn。"),
    PluginUpdateCautionGrant("Overrides a caution verdict for the host's next resolved Git/subdirectory update after reviewing these findings. The next scan may differ if the source changes. A dangerous verdict still blocks publication.", "审核这些发现后，为主机下一次解析的 Git／子目录更新覆盖警告结论。如果来源更改，下次扫描可能不同。危险结论仍会阻止发布。", "shěn hé zhè xiē fā xiàn hòu，wèi zhǔ jī xià yī cì gēng xīn fù gài jǐng gào jié lùn。wēi xiǎn jié lùn réng huì zǔ zhǐ fā bù。"),
    PluginUpdateApproveNext("I reviewed the supplied details and authorize these flags for one further host update with the stated concurrency limits.", "我已审核提供的详情，并授权在上述并发限制下为另一次主机更新使用这些标志。", "wǒ yǐ shěn hé tí gōng de xiáng qíng，bìng shòu quán zài shàng shù xiàn zhì xià wèi lìng yī cì gēng xīn shǐ yòng zhè xiē biāo zhì。"),
    PluginUpdateMoved("The host reported a different catalog pin from the reviewed inventory. Inspect this change on the host; the request was not repeated.", "主机报告的目录版本与审核清单不同。请在主机检查此更改；请求未重复。", "zhǔ jī bào gào de mù lù bǎn běn yǔ shěn hé qīng dān bù tóng。qǐng zài zhǔ jī jiǎn chá；qǐng qiú wèi chóng fù。"),
    PluginUpdateResult("Host-reported plugin update result", "主机报告的插件更新结果", "zhǔ jī bào gào de chā jiàn gēng xīn jié guǒ"),
    PluginUpdateGitReported("Git update acknowledged. Its reply provides no revision, so inventory cannot independently verify which commit was updated.", "Git 更新已确认。回复没有版本，因此清单无法独立验证更新了哪个提交。", "Git gēng xīn yǐ què rèn。huí fù méi yǒu bǎn běn，yīn cǐ qīng dān wú fǎ dú lì yàn zhèng tí jiāo。"),
    PluginUpdateUnchanged("Host reports no change", "主机报告没有更改", "zhǔ jī bào gào méi yǒu gēng gǎi"),
    PluginUpdateObservation("Configuration observation is separate from byte identity, live activation, execution completion and which actor caused the change. A catalog pin can be a tag object rather than its checked-out commit.", "配置观察与字节身份、即时激活、执行完成和引起更改的操作者不同。目录版本可以是标签对象，而非检出的提交。", "pèi zhì guān chá yǔ zì jié shēn fèn、jí shí jī huó hé zhí xíng wán chéng bù tóng。mù lù bǎn běn kě yǐ shì biāo qiān duì xiàng。"),
    PluginRemove("Review plugin removal", "审核移除插件", "shěn hé yí chú chā jiàn"),
    PluginInstallDirectory("Installed directory identifier", "安装目录标识", "ān zhuāng mù lù biāo zhì"),
    PluginRemoveUnsupported("Removal needs a user/git install with an exact directory under this verified profile's plugin root and no known target collision. Refresh management and plugin inventory, or inspect it on the host.", "移除需要用户或 Git 安装、已验证配置插件根目录下的确切目录，且没有已知目标冲突。请刷新管理和插件清单，或在主机检查。", "yí chú xū yào yòng hù huò Git ān zhuāng、yǐ yàn zhèng pèi zhì chā jiàn gēn mù lù xià de què qiè mù lù，qiě méi yǒu yǐ zhī mù biāo chōng tū。"),
    PluginRemoveEffect("Removes this installed directory, including local edits and any desktop half inside it, plus install metadata. Hermes clears related allow/deny entries, saved platform toolsets and local plugin grant records; it may reset the selected memory provider. A directory symlink removes only that link. Separate desktop copies and provider credentials may remain. Running handlers and existing work can continue until restart.", "移除此安装目录，包括本地编辑、其中的桌面部分及安装元数据。Hermes 会清除相关启用／停用记录、已保存的平台工具集和本地插件授权记录，并可能重置所选记忆提供方。目录符号链接仅删除链接本身。单独的桌面副本和提供方凭据可能保留。运行中的处理程序和现有工作可持续至重启。", "yí chú cǐ ān zhuāng mù lù，bāo kuò běn dì biān jí、qí zhōng de zhuō miàn bù fèn jí ān zhuāng yuán shù jù。Hermes huì qīng chú xiāng guān jì lù、gōng jù jí hé běn dì chā jiàn shòu quán，bìng kě néng chóng zhì jì yì tí gōng fāng。"),
    PluginRemoveLimit("The app rechecks profile mapping and inventory before one removal. Host edits can still race; no directory revision compare-and-set exists. Locked Windows files can remain pending deletion after the plugin stops appearing in inventory. A reply or inventory absence does not prove file erasure, provider revocation or stopped execution. Cancellation does not stop host cleanup. Lost replies are uncertain and never automatically repeated.", "应用会在一次移除前重新检查配置映射和清单。主机编辑仍可能冲突；目录没有版本比较后设置。插件不再出现在清单后，锁定的 Windows 文件仍可能等待删除。回复或清单缺失不能证明文件已擦除、提供方授权已撤销或执行已停止。取消不会停止主机清理。丢失回复是不确定结果，绝不自动重复。", "yìng yòng huì zài yī cì yí chú qián chóng xīn jiǎn chá pèi zhì yìng shè hé qīng dān。qǔ xiāo bú huì tíng zhǐ zhǔ jī qīng lǐ。diū shī huí fù shì bù què dìng jié guǒ，jué bù zì dòng chóng fù。"),
    PluginRemoveReported("Host acknowledged removal; inspect reported configuration separately from files and running work.", "主机已确认移除；请将报告配置与文件和运行中的工作分开检查。", "zhǔ jī yǐ què rèn yí chú；qǐng jiāng bào gào pèi zhì yǔ wén jiàn hé yùn xíng zhōng de gōng zuò fēn kāi jiǎn chá。"),
    PluginRemoveNotReported("The selected install is no longer reported. No removal was sent. Inspect host files separately.", "不再报告所选安装。未发送移除请求。请单独检查主机文件。", "bù zài bào gào suǒ xuǎn ān zhuāng。wèi fā sòng yí chú qǐng qiú。qǐng dān dú jiǎn chá zhǔ jī wén jiàn。"),
    PluginMemoryProviderCleared("Host reports memory-provider selection reset", "主机报告已重置记忆提供方选择", "zhǔ jī bào gào yǐ chóng zhì jì yì tí gōng fāng xuǎn zé"),
    PluginRemoveObservation("Verification means this user install is no longer reported. A bundled or package fallback may still appear under the same key. It does not prove bytes were erased, grants revoked at the provider, or execution stopped.", "验证表示不再报告此用户安装。同一键下仍可能出现内置或软件包回退。它不能证明字节已擦除、提供方授权已撤销或执行已停止。", "yàn zhèng biǎo shì bù zài bào gào cǐ yòng hù ān zhuāng。tóng yī jiàn xià réng kě néng chū xiàn huí tuì。tā bù néng zhèng míng zì jié yǐ cā chú、shòu quán yǐ chè xiāo huò zhí xíng yǐ tíng zhǐ。"),
    PluginEnable("Review plugin enable", "审核启用插件", "shěn hé qǐ yòng chā jiàn"),
    PluginDisable("Review plugin disable", "审核停用插件", "shěn hé tíng yòng chā jiàn"),
    PluginToggleUnsupported("The reported state or canonical key cannot be safely addressed here. Refresh and inspect it on the host.", "无法在此安全指定报告状态或规范键。请刷新并在主机检查。", "wú fǎ zài cǐ ān quán zhǐ dìng bào gào zhuàng tài huò guī fàn jiàn。qǐng shuā xīn bìng zài zhǔ jī jiǎn chá。"),
    PluginEnableEffect("Enabling changes this profile's plugin selection and can change the host dependency environment shared with other profiles, load host code, wire handlers and add its toolset to saved platform selections. Live features, new-session features and restart requirements are separate host reports.", "启用会更改此配置的插件选择，可能更改与其他配置共享的主机依赖环境、加载主机代码、连接处理程序并向已保存的平台选择添加工具集。即时功能、新会话功能和重启要求是独立的主机报告。", "qǐ yòng huì gēng gǎi cǐ pèi zhì de chā jiàn xuǎn zé，kě néng zhǔn bèi yī lài huán jìng、jiā zǎi zhǔ jī dài mǎ、lián jiē chǔ lǐ chéng xù bìng tiān jiā gōng jù jí。"),
    PluginDisableEffect("Disabling changes configuration, can change the shared host dependency environment, and removes its toolset from saved platform selections. Running gateway handlers remain loaded until restart; existing work may continue. This does not stop a plugin, revoke its credentials or remove its files.", "停用会更改配置，可能更改共享主机依赖环境，并从已保存的平台选择移除工具集。运行中的网关处理程序在重启前仍保持加载；现有工作可能继续。这不会停止插件、撤销凭据或删除文件。", "tíng yòng huì gēng gǎi pèi zhì bìng yí chú gōng jù jí。yùn xíng zhōng de wǎng guān chǔ lǐ chéng xù zài chóng qǐ qián réng bǎo chí jiā zǎi；xiàn yǒu gōng zuò kě néng jì xù。"),
    PluginToggleLimit("The app checks fresh inventory before one change and reads configuration afterward. Concurrent host edits can still race; there is no plugin revision compare-and-set. Waiting or cancellation does not stop host work. Lost replies are retained as uncertain and never automatically repeated.", "应用会在一次更改前检查最新清单，随后读取配置。并发主机编辑仍可能冲突；插件没有版本比较后设置。等待或取消不会停止主机工作。丢失回复会保留为不确定，绝不自动重复。", "yìng yòng huì zài yī cì gēng gǎi qián jiǎn chá zuì xīn qīng dān，suí hòu dú qǔ pèi zhì。diū shī huí fù huì bǎo liú wéi bù què dìng，jué bù zì dòng chóng fù。"),
    PluginToggleReported("Host-reported plugin change", "主机报告的插件更改", "zhǔ jī bào gào de chā jiàn gēng gǎi"),
    PluginToggleDetailsUnavailable("The host acknowledged the plugin change; optional activation details are unavailable.", "主机已确认插件更改；可选激活详情不可用。", "zhǔ jī yǐ què rèn chā jiàn gēng gǎi；kě xuǎn jī huó xiáng qíng bù kě yòng。"),
    PluginToggleObservation("Configuration observation does not prove live runtime state, completed execution or which actor caused it.", "配置观察不能证明实时运行状态、执行完成或由哪个操作者引起。", "pèi zhì guān chá bù néng zhèng míng shí shí yùn xíng zhuàng tài、zhí xíng wán chéng huò yóu nǎ gè cāo zuò zhě yǐn qǐ。"),
    PluginInstall("Review agent plugin installation","审核智能体插件安装","Shěnhé zhìnéngtǐ chājiàn ānzhuāng"),
    PluginInstallEnable("Enable through this installation request","通过此次安装请求启用","Tōngguò cǐ cì ānzhuāng qǐngqiú qǐyòng"),
    PluginInstallUnsupported("Installation needs an inspected agent component, HTTPS/SSH source and supported commit. Desktop UI components require the host desktop app.","安装需要检查过的智能体组件、HTTPS/SSH 源及受支持的提交。桌面界面组件需要主机桌面应用。","Ānzhuāng xūyào jiǎnchá guò de zhìnéngtǐ zǔjiàn, HTTPS/SSH yuán jí shòu zhīchí de tíjiāo. Zhuōmiàn jièmiàn zǔjiàn xūyào zhǔjī zhuōmiàn yìngyòng."),
    PluginApprovedCommit("Approved commit","批准的提交","Pīzhǔn de tíjiāo"),
    PluginEnableRequested("Enable requested by this installation","此次安装请求启用","Cǐ cì ānzhuāng qǐngqiú qǐyòng"),
    PluginEnableNotRequested("Enable was not requested; host configuration can still select installed code.","未请求启用；主机配置仍可能选择已安装代码。","Wèi qǐngqiú qǐyòng; zhǔjī pèizhì réng kěnéng xuǎnzé yǐ ānzhuāng dàimǎ."),
    PluginInstallEffect("Installs agent plugin files on the selected host/profile without force replacement. Plugin code uses host resources available to Hermes. Its desktop UI does not run in Android. Inspection detects components, not code safety.","在所选主机和配置安装智能体插件文件，不强制替换。插件代码使用 Hermes 可访问的主机资源。其桌面界面不在 Android 中运行。检查识别组件，不代表代码安全。","Zài suǒ xuǎn zhǔjī hé pèizhì ānzhuāng zhìnéngtǐ chājiàn wénjiàn, bù qiángzhì tìhuàn. Chājiàn dàimǎ shǐyòng Hermes kě fǎngwèn de zhǔjī zīyuán. Qí zhuōmiàn jièmiàn bù zài Android zhōng yùnxíng. Jiǎnchá shíbié zǔjiàn, bù dàibiǎo dàimǎ ānquán."),
    PluginInstallEnableEffect("Enabling also authorizes Hermes to prepare the plugin's Python dependencies and activate it. Reported live features, features deferred to a new session and restart requirements are separate.","启用也授权 Hermes 准备插件的 Python 依赖并激活插件。报告的即时功能、新会话生效功能和重启要求分别处理。","Qǐyòng yě shòuquán Hermes zhǔnbèi chājiàn de Python yīlài bìng jīhuó chājiàn. Bàogào de jíshí gōngnéng, xīn huìhuà shēngxiào gōngnéng hé chóngqǐ yāoqiú fēnbié chǔlǐ."),
    PluginInstallGuardEffect("Hermes checks the inspected commit before publication. Catalog source/path metadata can change after preflight. Waiting is bounded to ten minutes; cancellation or a lost reply does not stop host work. An uncertain request is never repeated automatically.","Hermes 在发布前检查已检查的提交。预检后目录源或路径元数据仍可能变化。等待最长十分钟；取消或丢失回复不会停止主机任务。不确定的请求绝不自动重复。","Hermes zài fābù qián jiǎnchá yǐ jiǎnchá de tíjiāo. Yùjiǎn hòu mùlù yuán huò lùjìng yuán shùjù réng kěnéng biànhuà. Děngdài zuì cháng shí fēnzhōng; qǔxiāo huò diūshī huífù bú huì tíngzhǐ zhǔjī rènwù. Bù quèdìng de qǐngqiú jué bù zìdòng chóngfù."),
    PluginInstallReported("Host reports plugin installation; activation and current configuration are separate observations.","主机报告插件已安装；激活与当前配置需分别观察。","Zhǔjī bàogào chājiàn yǐ ānzhuāng; jīhuó yǔ dāngqián pèizhì xū fēnbié guānchá."),
    PluginInstallSourceChanged("Hermes refused publication because the source moved. Inspect and review it again.","源已变化，Hermes 拒绝发布。请重新检查并审核。","Yuán yǐ biànhuà, Hermes jùjué fābù. Qǐng chóngxīn jiǎnchá bìng shěnhé."),
    PluginInstallDetailsUnavailable("Installation acknowledgement was retained; optional activation details were unavailable.","已保留安装确认；可选激活详情不可用。","Yǐ bǎoliú ānzhuāng quèrèn; kěxuǎn jīhuó xiángqíng bù kěyòng."),
    PluginRestartRequired("Host reports restart required","主机报告需要重启","Zhǔjī bàogào xūyào chóngqǐ"),
    PluginGatewayReloaded("Host reports gateway reload","主机报告网关已重新加载","Zhǔjī bàogào wǎngguān yǐ chóngxīn jiāzài"),
    PluginPythonDependencyCount("Reported Python dependency count","报告的 Python 依赖数量","Bàogào de Python yīlài shùliàng"),
    PluginMissingEnv("Host environment keys needed","需要的主机环境变量名称","Xūyào de zhǔjī huánjìng biànliàng míngchēng"),
    PluginActivatedNow("Host reports active now","主机报告即时激活","Zhǔjī bàogào jíshí jīhuó"),
    PluginDeferred("Deferred until a new session","新会话生效","Xīn huìhuà shēngxiào"),
    PluginReportedLive("Host reports available in open chats","主机报告在现有聊天可用","Zhǔjī bàogào zài xiànyǒu liáotiān kěyòng"),
    PluginActivationUnavailable("Activation details were not reported.","未报告激活详情。","Wèi bàogào jīhuó xiángqíng."),
    PluginHostDetails("Inspect host setup/logs for missing dependencies or server errors.","请检查主机设置或日志，了解缺少的依赖或服务器错误。","Qǐng jiǎnchá zhǔjī shèzhì huò rìzhì, liǎojiě quēshǎo de yīlài huò fúwùqì cuòwù."),
    PluginReportedYes("Yes","是","Shì"),
    PluginReportedNo("No","否","Fǒu"),

    PluginCatalog("Plugin catalog and sources","插件目录与源","Chājiàn mùlù yǔ yuán"),
    PluginFeatured("Featured for this host","此主机的精选插件","Cǐ zhǔjī de jīngxuǎn chājiàn"),
    PluginCatalogName("Catalog plugin name","目录插件名称","Mùlù chājiàn míngchēng"),
